/* Original procedural instrument. No prerecorded music, microphone or upload. */
const ZONES={studio:{name:'STUDIO',frequencies:[55,82.41,110],type:'triangle'},street:{name:'ULICE',frequencies:[73.42,110,146.83],type:'sine'},library:{name:'KNIHOVNA',frequencies:[130.81,196,261.63],type:'sine'}};
