export function tapTempo(taps){const valid=(Array.isArray(taps)?taps:[]).filter(Number.isFinite).slice(-9),intervals=[];for(let i=1;i<valid.length;i++){const delta=valid[i]-valid[i-1];if(delta>=270&&delta<=1500)intervals.push(delta);}if(intervals.length<2)return null;intervals.sort((a,b)=>a-b);const mid=intervals.length>>1,median=intervals.length%2?intervals[mid]:(intervals[mid-1]+intervals[mid])/2;return Math.round(clamp(60000/median,40,220));}
export function normalizeSound(value){const s=value&&typeof value==='object'?value:{};return {volume:Number.isFinite(s.volume)?clamp(s.volume,0,.5):.18,zone:Object.hasOwn(ZONES,s.zone)?s.zone:'studio',follow:s.follow!==false,bpm:Number.isFinite(s.bpm)?Math.round(clamp(s.bpm,40,220)):90,steps:Array.from({length:8},(_,i)=>MIDI.includes(s.steps?.[i])?s.steps[i]:[48,-1,55,-1,53,-1,57,60][i]),length:s.length===4?4:8,gesture:(Array.isArray(s.gesture)?s.gesture:[]).filter(p=>p&&[p.x,p.y,p.t].every(Number.isFinite)).slice(0,1000).map(p=>({x:clamp(p.x,0,900),y:clamp(p.y,0,260),t:clamp(p.t,0,30000)}))};}
export function cadenceStroke(points){return {color:'#FFD600',width:7,points:(Array.isArray(points)?points:[]).filter(p=>Number.isFinite(p?.t)&&Number.isFinite(p?.level)).slice(0,800).map(p=>[clamp(p.t,0,12)/12*900,220-clamp(p.level,0,1)*160])};}
export function midiFrequency(note){return 440*Math.pow(2,(note-69)/12);}
export function zoneForPanel(panel){return ({base:'studio',quests:'library',workshop:'studio',field:'street',journal:'library'})[panel]||'studio';}
