  const message=text=>{$('.sound-status').textContent=text;notify(text);};
  function persist(){clearTimeout(saveTimer);saveTimer=setTimeout(()=>{const ok=store.update(s=>{s.drafts.sound=structuredClone(state);});if(!ok)message('Nastavení je jen v paměti. Lokální uložení se nepodařilo potvrdit.');},200);}
  function emitLevel(level=0,bands=[0,0,0]){window.dispatchEvent(new CustomEvent('caisik:audiolevel',{detail:{level,bands}}));}
  function refreshTransport(){transport.hidden=!(zoneRunning||motifRunning||gestureVoice||(file&&!file.paused));$('.sound-lab').dataset.running=String(!transport.hidden);}
  async function unlock(){if(disposed||document.hidden)return false;const epoch=transportEpoch,serial=++unlockSerial;const Constructor=window.AudioContext||window.webkitAudioContext;if(!Constructor){message('Web Audio v tomto prohlížeči není dostupné. Noty, rytmus a gesta můžeš připravit a uložit bez zvuku.');return false;}try{if(!ctx){ctx=new Constructor();master=ctx.createGain();master.gain.value=muted?0:state.volume;master.connect(ctx.destination);}if(ctx.state==='suspended')await ctx.resume();if(disposed){if(ctx.state!=='closed')await ctx.close();return false;}if(serial!==unlockSerial)return false;if(epoch!==transportEpoch||document.hidden){if(ctx.state==='running')await ctx.suspend();return false;}return true;}catch{message('Zvuk se nepodařilo odemknout. Zkus přehrávání znovu tlačítkem; textová dílna zůstává dostupná.');return false;}}
