  function note(note,duration=.2){if(!ctx||!master||ctx.state!=='running')return;const osc=ctx.createOscillator(),gain=ctx.createGain(),now=ctx.currentTime;osc.type='triangle';osc.frequency.value=midiFrequency(note);gain.gain.setValueAtTime(0,now);gain.gain.linearRampToValueAtTime(.24,now+.015);gain.gain.exponentialRampToValueAtTime(.001,now+duration);osc.connect(gain);gain.connect(master);const voice={osc,gain};voices.add(voice);osc.onended=()=>stopVoice(voice);osc.start(now);osc.stop(now+duration+.03);}
  function makeZones(){if(zoneNodes.size)return;for(const [key,z] of Object.entries(ZONES)){const groupGain=ctx.createGain();groupGain.gain.value=0;groupGain.connect(master);const oscillators=z.frequencies.map((frequency,i)=>{const osc=ctx.createOscillator(),gain=ctx.createGain();osc.type=z.type;osc.frequency.value=frequency;gain.gain.value=.035/(i+1);osc.connect(gain);gain.connect(groupGain);osc.start();return {osc,gain};});zoneNodes.set(key,{gain:groupGain,oscillators});}}
  function changeZone(zone){if(!Object.hasOwn(ZONES,zone))return;state.zone=zone;const select=$('[data-sound="zone"]');if(select)select.querySelectorAll('option').forEach(option=>{option.selected=option.getAttribute('value')===zone;});$('[data-zone-name]').textContent=ZONES[zone].name;if(zoneRunning&&ctx){for(const [key,nodes] of zoneNodes){const p=nodes.gain.gain;p.cancelScheduledValues(ctx.currentTime);p.setValueAtTime(p.value,ctx.currentTime);p.linearRampToValueAtTime(key===zone?1:0,ctx.currentTime+1.2);}}persist();}
